import {Stack} from '@primer/react'
import {Dialog} from '@primer/react/experimental'

import {MetadataGroupTable} from './MetadataGroupTable'
import type {MetadataDrawerProps} from './types'

/**
 * A standalone drawer/sidesheet that displays grouped metadata tables.
 * Each group is rendered with a title and table using MetadataGroupTable.
 *
 * This is a composable component - use it alongside MetadataPreviewTable components
 * to create flexible metadata display layouts.
 */
export const MetadataDrawer = ({
  groups,
  title,
  ariaLabel = 'Metadata',
  isOpen,
  onClose,
  returnFocusRef,
  onCopy,
}: MetadataDrawerProps) => {
  if (!isOpen) return null

  return (
    <Dialog title={title} onClose={onClose} position="right" returnFocusRef={returnFocusRef} width="large">
      <Stack direction="vertical" gap="normal" padding="none">
        {groups.map(group => (
          <MetadataGroupTable
            key={group.name}
            group={group}
            ariaLabel={`${ariaLabel} - ${group.name}`}
            onCopy={onCopy}
          />
        ))}
      </Stack>
    </Dialog>
  )
}

export default MetadataDrawer
