import {queryOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

import {secretScanningAlertTimelinePath} from '../paths'
import type {Timeline} from '../types/alert-types'

export const queries = {
  timeline: (alertNumber: number, owner: string, repo: string, shouldRefetchTimeline: number) =>
    queryOptions({
      queryKey: ['secret-scanning', 'timeline', alertNumber, owner, repo, shouldRefetchTimeline] as const,
      queryFn: async (): Promise<Timeline> => {
        const response = await reactFetchJSON(secretScanningAlertTimelinePath({owner, repo, id: alertNumber}), {
          method: 'GET',
        })
        if (!response.ok) {
          throw new Error('fetch failed')
        }
        const data = await response.json()
        if (!data?.timeline) {
          throw new Error('timeline not found')
        }
        return data.timeline
      },
    }),
}
