import {queryOptions, useMutation, useQueryClient} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

import {secretScanningTokenReportPath, secretScanningTokenValidationStatus} from '../paths'
import type {OnDemandValidation, ReportTokenResponse} from '../types/alert-types'

export const validationQueries = {
  // TODO: Migrate this to useMutationState?
  // This is just used as state/cache
  validationCache: (alertNumber: number) =>
    queryOptions<OnDemandValidation>({
      queryKey: ['secret-scanning', 'validation-result', alertNumber] as const,
      enabled: false,
      queryFn: () => {
        throw new Error('it should never be called from here!')
      },
    }),

  // TODO: Migrate PUT calls to useMutation
  reportToken: (alertNumber: number, owner: string, repo: string) =>
    queryOptions<ReportTokenResponse>({
      queryKey: [
        'secret-scanning',
        'report',
        alertNumber,
        secretScanningTokenReportPath(owner, repo, alertNumber),
      ] as const,
      queryFn: async () => {
        const result = await reactFetchJSON(secretScanningTokenReportPath(owner, repo, alertNumber), {
          method: 'put',
        })
        if (!result.ok) {
          const errorText = await result.text()
          throw new Error(errorText)
        }
        const updatedValidity = await result.json()
        if (!updatedValidity.data) {
          throw new Error('Error reporting token')
        }
        return updatedValidity.data
      },
      enabled: false,
      retry: false,
    }),
}

export function useValidateTokenMutation({
  owner,
  repo,
  alertNumber,
  onSuccess,
  onError,
  onMutate,
}: {
  owner: string
  repo: string
  alertNumber: number
  onSuccess?: (data: OnDemandValidation) => void
  onError?: () => void
  onMutate?: () => void
}) {
  const qc = useQueryClient()
  return useMutation<OnDemandValidation>({
    mutationFn: async () => {
      const response = await reactFetchJSON(
        secretScanningTokenValidationStatus({owner, repo, tokenNumber: alertNumber}),
        {method: 'PUT'},
      )
      if (!response.ok) {
        throw new Error('fetch failed')
      }
      const updatedValidity = await response.json()
      if (updatedValidity.data) {
        return updatedValidity.data
      }
      throw new Error('No data in response')
    },
    onMutate,
    onSuccess: data => {
      qc.setQueryData(validationQueries.validationCache(alertNumber).queryKey, data)
      onSuccess?.(data)
    },
    onError,
  })
}
