import {ActionList} from '@primer/react'
import type {RelatedPublicLeaks, RelatedPublicLeak} from '../../../types/alert-types'
import {TokenMetadataSection} from './TokenMetadataSection'
import {isContentLocation, isRepoBlobLocation} from '../../../types/location-types'
import {blobPath} from '@github-ui/paths'
import styles from './RelatedPublicLeaksPane.module.css'
import {FileIcon} from '@primer/octicons-react'
import type {Repository} from '../../../types/repo-types'
import {getContentPath} from '../../../paths'

export function RelatedPublicLeaksPane({
  relatedPublicLeaks,
  repository,
}: {
  relatedPublicLeaks: RelatedPublicLeaks
  repository: Repository
}) {
  return (
    <TokenMetadataSection sectionName="Public leaks">
      {repository.visibility === 'public' && <span>This secret was leaked in this public repository.</span>}
      {relatedPublicLeaks.leaks.length === 0 && repository.visibility !== 'public' && (
        <span>This secret was leaked in at least one public repository which is currently unavailable.</span>
      )}
      <ActionList variant="full" className={styles.leaksList}>
        {relatedPublicLeaks.leaks.map(leak => (
          <PublicLeakLink key={leak.repository_id} leak={leak} />
        ))}
      </ActionList>
      {relatedPublicLeaks.more_exist && relatedPublicLeaks.leaks.length === 5 && (
        <span>Note: this list is not exhaustive.</span>
      )}
    </TokenMetadataSection>
  )
}

function PublicLeakLink({leak}: {leak: RelatedPublicLeak}) {
  if (isContentLocation(leak.location)) {
    const contentPath = getContentPath(
      {name: leak.repository_name, owner_display_login: leak.repository_owner},
      leak.location.content_type,
      leak.location.content_number,
      leak.location.content_id,
    )
    const displayPath = rtlProofPath(contentPath)
    return (
      <ActionList.LinkItem href={contentPath}>
        <ActionList.LeadingVisual>
          <FileIcon />
        </ActionList.LeadingVisual>
        <span className="text-normal">{displayPath}</span>
      </ActionList.LinkItem>
    )
  }

  if (isRepoBlobLocation(leak.location)) {
    const leakPath = blobPath({
      owner: leak.repository_owner,
      repo: leak.repository_name,
      commitish: leak.location.commit.oid,
      filePath: leak.location.path,
      lineNumber: leak.location.start_line,
    })
    const displayPath = rtlProofPath(`${leak.repository_owner}/${leak.repository_name}/${leak.location.path}`)
    const displayCommit = leak.location.commit.oid.slice(0, 7)
    return (
      <ActionList.LinkItem href={leakPath}>
        <ActionList.LeadingVisual>
          <FileIcon />
        </ActionList.LeadingVisual>
        <span className="text-normal">{displayPath}</span>
        <ActionList.Description className="text-mono">{displayCommit}</ActionList.Description>
      </ActionList.LinkItem>
    )
  }
}

// This accounts for file names and paths beginning with `.` which would otherwise get rendered as e.g.
// `github/workflows/main.yml.` instead of the proper `.github/workflows/main.yml`
function rtlProofPath(filePath: string) {
  // The unicode character below is a left-to-right mark (https://en.wikipedia.org/wiki/Left-to-right_mark)
  // which prevents the browser from rendering the string right-to-left as set by the CSS for the element
  // calling this function.
  if (filePath.startsWith('.') || filePath.startsWith('/')) {
    return `\u200E${filePath}`
  }

  return filePath
}
