import {useEffect, useRef} from 'react'
import {useQuery} from '@github-ui/react-query'
import {metadataQueries} from '../../../api/metadata'
import type {Repository} from '../../../types/repo-types'

type UseGetPartnerDataProps = {
  alertNumber: number
  enabled: boolean
  repo: Repository
  validity: string
  // Invoked once, the first time a metadata fetch resolves with data.
  onMetadataFetched?: () => void
}

export function useGetPartnerData({alertNumber, enabled, repo, validity, onMetadataFetched}: UseGetPartnerDataProps) {
  const {name, owner_display_login: owner} = repo

  const query = useQuery({
    ...metadataQueries.partnerMetadataWithValidity(alertNumber, owner, name, validity),
    enabled,
    select: response => response.metadata,
  })

  const hasNotifiedRef = useRef(false)
  useEffect(() => {
    if (query.data && !hasNotifiedRef.current) {
      hasNotifiedRef.current = true
      onMetadataFetched?.()
    }
  }, [query.data, onMetadataFetched])

  return query
}
