import {queryOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

import {secretScanningPartnerTokenMetadataPath, secretScanningTokenMetadataOrgAccessPath} from '../paths'
import type {TokenAccess} from '../types/token-metadata-types'
import type {DisplayedUser} from '../types/user-types'

export type PartnerTokenMetadata = {
  secret_id?: string
  secret_name?: string
  owner_id?: string
  owner_name?: string
  owner_email?: string
  org_name?: string
  org_id?: string
  secret_issued_at?: string
  secret_expires_at?: string
  secret_last_used_at?: string
  org_access?: TokenAccess
  kvps?: PartnerMetadataKVP[]
  github_metadata?: GitHubTokenMetadataInfo
}

export type PartnerMetadataKVP = {
  key: string
  value: string
}

export type GitHubTokenMetadataInfo = {
  link?: string
  owner?: DisplayedUser
  is_owner_suspended?: boolean
}

type PartnerMetadataApiResponse = {
  metadata?: PartnerTokenMetadata
}

export const metadataQueries = {
  partnerMetadata: (alertNumber: number, owner: string, repo: string) =>
    queryOptions<PartnerMetadataApiResponse['metadata']>({
      queryKey: ['secret-scanning-metadata', alertNumber, owner, repo] as const,
      queryFn: async () => {
        const response = await reactFetchJSON(secretScanningPartnerTokenMetadataPath(owner, repo, alertNumber), {
          method: 'GET',
        })
        if (!response.ok) {
          throw new Error('fetch failed')
        }
        const data = await response.json()
        return data.metadata
      },
    }),

  partnerMetadataWithValidity: (alertNumber: number, owner: string, repo: string, validity: string) =>
    queryOptions<PartnerMetadataApiResponse>({
      queryKey: ['secret-scanning-metadata', alertNumber, owner, repo, validity] as const,
      queryFn: async () => {
        const response = await reactFetchJSON(secretScanningPartnerTokenMetadataPath(owner, repo, alertNumber))
        if (!response.ok) {
          throw new Error(`Partner metadata fetch failed: ${response.status} ${response.statusText}`)
        }
        return response.json()
      },
    }),

  orgAccess: (tokenNumber: number, owner: string, repo: string, accessId: number, tokenType: string) =>
    queryOptions<TokenAccess>({
      queryKey: ['secret-scanning', 'org-access', tokenNumber, owner, repo, accessId, tokenType] as const,
      queryFn: async () => {
        const response = await reactFetchJSON(
          secretScanningTokenMetadataOrgAccessPath({
            repo,
            owner,
            accessId,
            tokenType,
            tokenNumber,
          }),
          {method: 'GET'},
        )
        if (!response.ok) {
          throw new Error('Failed to fetch org access')
        }
        const json = await response.json()
        return json.org_access
      },
    }),
}
