import {Fragment, useState} from 'react'
import {Button, Link, RelativeTime} from '@primer/react'
import {AlertIcon, SkipIcon} from '@primer/octicons-react'
import {type TokenGroup, TokenVerificationStatus} from '../../../types/alert-types'
import type {Repository} from '../../../types/repo-types'
import {secretScanningAlertPath} from '../../../paths'

export function Multipart({
  tokenGroups,
  repo,
  alertNumber,
  automaticValidityChecksEnabled,
  onDemandChecksSupported,
  tokenType,
  awsKeyIdStandaloneEnabled,
}: {
  tokenGroups: TokenGroup[]
  repo: Repository
  alertNumber: number
  automaticValidityChecksEnabled: boolean
  onDemandChecksSupported: boolean
  tokenType: string
  awsKeyIdStandaloneEnabled: boolean
}) {
  const [isOpen, setIsOpen] = useState(false)
  const groupsToDisplay = tokenGroups
    .map(group => ({
      group,
      membersToDisplay: group.members.filter(part => part.number !== alertNumber),
    }))
    .filter(({membersToDisplay}) => membersToDisplay.length > 0)

  if (tokenGroups.length === 0 && automaticValidityChecksEnabled && onDemandChecksSupported) {
    const awsStandaloneEnabled = tokenType === 'AWS_KEYID' && awsKeyIdStandaloneEnabled
    return (
      <div className="py-2" data-testid="multipart-no-groups-found">
        {awsStandaloneEnabled
          ? 'This token is currently not part of a detected set of credentials.'
          : 'This token is currently not part of a detected set of credentials. Verification is not supported for individual tokens.'}
      </div>
    )
  }

  if (groupsToDisplay.length === 0) return null
  return (
    <div data-testid="multipart">
      {!isOpen && (
        <Button onClick={() => setIsOpen(true)} variant="invisible" className="mt-1 p-1 text-normal">
          Show tokens used with this secret
        </Button>
      )}
      {isOpen && (
        <>
          <Button onClick={() => setIsOpen(false)} variant="invisible" className="mt-1 p-1 text-normal">
            Hide tokens used with this secret
          </Button>
          {groupsToDisplay.map(({group, membersToDisplay}, i) => {
            return (
              // eslint-disable-next-line @eslint-react/no-array-index-key
              <div key={i} className="tmp-pl-3 d-flex">
                {membersToDisplay.map((part, memberIdx) => {
                  const lastMember = memberIdx === membersToDisplay.length - 1
                  return (
                    <Fragment key={part.number}>
                      <Link href={secretScanningAlertPath(repo.owner_display_login, repo.name, part.number)} inline>
                        {part.label} #{part.number}
                      </Link>
                      {!lastMember && <>,&nbsp;</>}
                    </Fragment>
                  )
                })}
                <div className="ml-1">
                  <GroupActivity group={group} />
                  {group.validity_last_checked && (
                    <>
                      &nbsp;as of&nbsp;
                      <RelativeTime date={new Date(group.validity_last_checked)} precision="second" />
                    </>
                  )}
                </div>
              </div>
            )
          })}
        </>
      )}
    </div>
  )
}

function GroupActivity({group}: {group: TokenGroup}) {
  return group.validity === TokenVerificationStatus.TOKEN_VALIDITY_ACTIVE ? (
    <>
      <AlertIcon className="text-bold fgColor-danger" />
      <span className="fgColor-danger text-semibold"> Active set</span>
    </>
  ) : (
    <>
      <SkipIcon className="text-bold fgColor-muted" />
      <span className="fgColor-danger text-semibold"> Inactive set</span>
    </>
  )
}
