import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {Stack, Text} from '@primer/react'
import {clsx} from 'clsx'

import styles from './MetadataTable.module.css'
import type {MetadataTableProps} from './types'

export const MetadataTable = ({title, items, footerContent, onCopy, withBorder}: MetadataTableProps) => {
  const hasTitle = Boolean(title)

  return (
    <div
      className={clsx('rounded-2 overflow-hidden', {
        f6: hasTitle,
        border: withBorder,
        'bgColor-muted tmp-py-1': !withBorder,
      })}
    >
      <table className={styles.MetadataGroupTable} width="100%">
        {title && (
          <Text
            as="caption"
            size="medium"
            weight="medium"
            className={clsx('bgColor-muted text-left tmp-px-3 tmp-py-2', {'border-bottom': withBorder})}
          >
            {title}
          </Text>
        )}
        <tbody>
          {items.map(({id, field, value, trailingContent, showCopyButton}) => (
            <tr key={id} className={clsx(styles.MetadataGroupRow, {'border-0': !withBorder})}>
              <th
                scope="row"
                className={clsx(styles.MetadataKey, 'text-left text-wrap-balance tmp-pl-3 tmp-pr-1 tmp-py-2', {
                  f6: hasTitle,
                })}
              >
                <Text weight="semibold" className="wb-break-word">
                  {field}
                </Text>
              </th>
              <td colSpan={3} className={clsx('tmp-px-1', styles.MetadataValue)}>
                <Stack direction="horizontal" gap="condensed" align="center">
                  <div className="min-width-0">
                    {trailingContent || <div className="tmp-py-2 text-wrap-balance wb-break-word">{value}</div>}
                  </div>
                  {showCopyButton && value && (
                    <span className={styles.MetadataCopyButton}>
                      <CopyToClipboardButton
                        ariaLabel={`Copy ${field}`}
                        textToCopy={value}
                        onCopy={() => onCopy?.(field, value)}
                        size="small"
                      />
                    </span>
                  )}
                </Stack>
              </td>
            </tr>
          ))}
        </tbody>
        {footerContent ? (
          <tfoot>
            <tr>
              <td colSpan={4} className={clsx('bgColor-muted tmp-px-3 tmp-py-2', {'border-top': withBorder})}>
                {footerContent}
              </td>
            </tr>
          </tfoot>
        ) : null}
      </table>
    </div>
  )
}

export default MetadataTable
